def main():
    for item in ('qseries_v2/oracle_strategy_intelligence/solana_money/mriya_python_paper_arb/crosslisted.py',
                 'qseries_v2/oracle_strategy_intelligence/solana_money/qarb_clean_bot/qarb_043b_paced_mriya_token_discovery.py',
                 'qseries_v2/oracle_strategy_intelligence/solana_money/qarb_clean_bot/qarb_045b_evidence_window_hotset_lifecycle.py',
                 'qseries_v2/oracle_strategy_intelligence/solana_money/qarb_clean_bot/qarb_071_continuous_mriya_replenishment.py'):
        if not Path(item).is_file():raise RuntimeError('REQUIRED_ORIGINAL_MODULE_MISSING: '+item)
    BASE.mkdir(parents=True,exist_ok=True)
    for name,content in PAYLOADS.items():
        (BASE/name).write_text(content,encoding='utf8')
    for name in ('run_oracle123.py','run_oracle120.py'):
        py_compile.compile(str(BASE/name),doraise=True)
    subprocess.run(['node','--check',str(BASE/'oracle123_atomic_machine.cjs')],check=True)
    checks=r"""
const assert=require('node:assert/strict');
const m=require('./qseries_v2/oracle_execution/solana_atomic_executor/oracle105_sdk_worker/oracle123_atomic_machine.cjs');
const r=(t,p,d,src='HISTORICAL_IDENTITY_ONLY',stage='OBSERVE')=>({token:t,pump_pool:p,meteora_pool:d,source:src,lifecycle:stage});
const c=[r('A','P1','D1'),r('A','P2','D2'),r('B','P3','D3','UNIVERSAL_LIVE_CROSSLIST','HOT'),r('C','P4','D4')];
let s=new Map(), now=1000000;
let first=m.selectBatch(c,s,2,now);assert.equal(first.length,2);assert.equal(new Set(first.map(x=>x.token)).size,2);
for(const x of first)s.set(m.identity(x),m.observeResult(null,{status:'HOLD_NO_EXECUTABLE_PROFIT',directions:[{status:'REJECT_QUOTE'}]},now));
let second=m.selectBatch(c,s,2,now+1000);assert.equal(second.length,2);
assert(second.some(x=>!first.some(y=>m.identity(y)===m.identity(x))));
assert.equal(m.isBidirectionallyQuoted({directions:[{direction:'PUMP_TO_METEORA',status:'REJECT_GROSS',min_sol_out:'1'},{direction:'METEORA_TO_PUMP',status:'REJECT_GROSS',min_sol_out:'1'}]}),true);
assert.equal(m.isBidirectionallyQuoted({directions:[{direction:'PUMP_TO_METEORA',status:'REJECT_QUOTE'},{direction:'METEORA_TO_PUMP',status:'REJECT_GROSS',min_sol_out:'1'}]}),false);
assert.equal(m.SIZE,10000000n);assert(m.is429(new Error('429 Too Many Requests')));
console.log('[PASS] ORACLE-123 fair token-diverse selection, cooldown, full-quote truth, fixed canary, RPC429');
"""
    subprocess.run(['node','-e',checks],check=True)
    print('[INSTALLED] ORACLE-123 universal PumpSwap/Meteora + Mriya discovery + fair activity-priority evaluator')
    print('[SAFETY] scanner untouched; signing=false; broadcasting=false')
    print('[LAUNCH] python oracle120_credentials.py --run')
if __name__=='__main__':main()
